/* Cross-factory asset monitoring, selected-asset context and real demo work orders. */
if(!assets.some(a=>a.id==='V-017'))assets.push({id:'V-017',name:'Control valve',area:'Process',skill:'Mechanical',health:62,risk:'Critical inspection',cost:28000,reading:'Position deviation 12%',target:'Position deviation below 5%',due:'Next planned shutdown',model:'valve'});
const maint={factory:state.factory>=0?state.factory:2,index:0,type:'All',status:'All',search:'',view:'assembly',zoom:1};
const maintArt=['pump','motor','compressor','valve'];
const maintTypes=['Pumps','Motors','Compressors','Valves'];
const maintCondition=[{label:'Vibration',value:4.8,unit:'mm/s',limit:4.5,second:'Motor temperature',secondary:'68 °C',hours:12480,series:[3.6,3.9,4.2,4.4,4.35,4.65,4.8]},{label:'Motor temperature',value:62,unit:'°C',limit:75,second:'Vibration',secondary:'1.2 mm/s',hours:8420,series:[57,58,59,61,63,61,62]},{label:'Discharge pressure',value:6.2,unit:'bar',limit:6.5,second:'Motor temperature',secondary:'59 °C',hours:18260,series:[6.1,6.2,6.1,6.3,6.2,6.1,6.2]},{label:'Position deviation',value:12,unit:'%',limit:5,second:'Supply pressure',secondary:'5.8 bar',hours:6580,series:[3,4,5,8,10,11,12]}];
const maintParts=[[{name:'Bearing',part:'6205',stock:4},{name:'Seal kit',part:'SK-TP104',stock:1},{name:'Coupling insert',part:'CI-38',stock:0}],[{name:'Motor bearing',part:'6206',stock:6},{name:'Cooling fan',part:'FAN-201',stock:2},{name:'Terminal block',part:'TB-100',stock:1}],[{name:'Air filter',part:'AF-C01',stock:2},{name:'Seal kit',part:'SK-C01',stock:2},{name:'Pressure valve',part:'PV-81',stock:1}],[{name:'Packing set',part:'PTFE-17',stock:1},{name:'Actuator kit',part:'AK-17',stock:0},{name:'Valve stem',part:'STM-017',stock:2}]];
function maintenanceCategory(index){return assets[index].health<70?'Critical':assets[index].health<90?'Attention':'Healthy'}
function maintenanceRecords(ignoreStatus=false){const q=maint.search.toLowerCase();return factories.flatMap((f,fi)=>assets.map((a,index)=>({factory:fi,index,asset:a,key:fi+'-'+index}))).filter(r=>(state.factory<0||r.factory===state.factory)&&(maint.type==='All'||maintTypes[r.index]===maint.type)&&(!q||[r.asset.id,r.asset.name,factories[r.factory].name,factories[r.factory].city,r.asset.area,...maintParts[r.index].map(p=>p.name+' '+p.part)].join(' ').toLowerCase().includes(q))&&(ignoreStatus||maint.status==='All'||maint.status==='Planned service'&&r.index===2||maintenanceCategory(r.index)===maint.status)).sort((a,b)=>((a.factory===maint.factory&&a.index===maint.index?-100:0)+a.index*4+a.factory)-((b.factory===maint.factory&&b.index===maint.index?-100:0)+b.index*4+b.factory))}
function maintAssetImage(index=maint.index,exploded=false){return 'assets/maintenance-'+(exploded?'pump-exploded':maintArt[index])+'.png'}
function maintenanceSummary(){const rows=maintenanceRecords(true);return [['Assets monitored',rows.length,'All'],['Healthy',rows.filter(r=>maintenanceCategory(r.index)==='Healthy').length,'Healthy'],['Attention required',rows.filter(r=>maintenanceCategory(r.index)==='Attention').length,'Attention'],['Critical',rows.filter(r=>maintenanceCategory(r.index)==='Critical').length,'Critical']].map((r,i)=>`<button class="maintenance-summary-card ${i===2?'amber-summary':i===3?'critical-summary':''}" onclick="setMaintenanceStatus('${r[2]}')"><span>${['▱','✓','△','!'][i]}</span><div><small>${r[0]}</small><strong>${r[1]}</strong></div></button>`).join('')}
function selectMaintenanceAsset(factory,index){if(!maintenanceRecords().some(r=>r.factory===factory&&r.index===index)){maint.type='All';maint.status='All';maint.search=''}maint.factory=factory;maint.index=index;op.asset=index;maint.view='assembly';maint.zoom=1;render()}
function setMaintenanceStatus(status){maint.status=status;render()}
function setMaintenanceType(type){maint.type=type;render()}
function setMaintenanceSearch(value){maint.search=value;render();const input=$('#maintenance-search');input?.focus?.();input?.setSelectionRange?.(value.length,value.length)}
function resetMaintenanceFilters(){maint.type='All';maint.status='All';maint.search='';render()}
function selectedMaintenanceHeader(){const a=assets[maint.index];return `${a.id} · ${a.name}`}
function maintenanceAssetRegister(rows){return `<section class="panel maintenance-register"><div class="panelhead"><h2>Asset register</h2><small>${rows.length} shown</small></div><input id="maintenance-search" type="search" value="${escapeHTML(maint.search)}" placeholder="Search asset, factory or part" oninput="setMaintenanceSearch(this.value)" aria-label="Search asset or part"><div class="maint-type-chips">${['All',...maintTypes].map(t=>opButton(t,`setMaintenanceType('${t}')`,maint.type===t?'active':'')).join('')}</div><div class="maintenance-register-list">${rows.map(r=>`<button class="maintenance-register-row ${r.factory===maint.factory&&r.index===maint.index?'selected':''}" onclick="selectMaintenanceAsset(${r.factory},${r.index})"><img src="${maintAssetImage(r.index)}" alt="3D-rendered ${r.asset.name}"><div><div class="row"><strong>${r.asset.id} · ${r.asset.name}</strong><b>${r.asset.health}%</b></div><small>${factories[r.factory].name} / ${r.asset.area}</small><span class="maint-state ${maintenanceCategory(r.index).toLowerCase()}">${r.asset.risk}</span></div></button>`).join('')||'<div class="maint-empty">No assets match the filters.<br>'+opButton('Clear filters','resetMaintenanceFilters()')+'</div>'}</div></section>`}
function maintenanceHotspots(){const parts=maint.index===0?[['Mechanical seal',24,65,1],['Bearing',43,42,0],['Coupling',58,63,2],['Motor',82,37,-1]]:maint.index===1?[['Drive shaft',20,57,0],['Cooling fan',82,43,1],['Terminal box',51,20,2]]:maint.index===2?[['Receiver tank',50,70,1],['Compressor head',31,25,0],['Motor',68,34,-1],['Outlet valve',82,59,2]]:[['Valve body',48,72,0],['Stem',49,47,2],['Actuator',49,22,1],['Positioner',70,46,-1]];return `<div class="maint-hotspots">${parts.map((p,i)=>`<button class="maint-component ${i===1?'advisory-component':''}" style="left:${p[1]}%;top:${p[2]}%" onclick="maintenancePartDetail(${p[3]})"><span>${p[0]}</span><i></i></button>`).join('')}</div>`}
function maintenancePipingDiagram(){return `<svg class="maintenance-piping" viewBox="0 0 800 380" aria-label="Illustrative selected-factory utility piping"><path d="M40 210H760M380 210V75H650V150" fill="none" stroke="#9ce9cf" stroke-width="9"/><g fill="#514653" stroke="#c8ffe4" stroke-width="2"><rect x="15" y="155" width="80" height="110" rx="18"/><rect x="705" y="155" width="80" height="110" rx="18"/></g><g fill="#fff" font-size="13" text-anchor="middle"><text x="55" y="212">Feed</text><text x="745" y="212">Process</text></g>${assets.map((a,i)=>`<g style="cursor:pointer" role="button" tabindex="0" onclick="selectMaintenanceAsset(${maint.factory},${i})" onkeydown="if(event.key==='Enter')selectMaintenanceAsset(${maint.factory},${i})"><circle cx="${170+i*150}" cy="210" r="43" fill="${i===maint.index?'#3b7662':'#534755'}" stroke="${i===maint.index?'#baffdf':'#acbfc1'}" stroke-width="2"/><text x="${170+i*150}" y="215" fill="#fff" text-anchor="middle" font-size="15">${a.id}</text><text x="${170+i*150}" y="282" fill="#e4d3e1" text-anchor="middle" font-size="11">${a.name}</text></g>`).join('')}<text x="400" y="340" text-anchor="middle" fill="#decbd9" font-size="11">Schematic connections only · Not an engineering P&amp;ID</text></svg>`}
function maintenanceAssembly(){const a=assets[maint.index];return `<section class="panel maintenance-assembly"><div class="panelhead"><div><h2>${selectedMaintenanceHeader()}</h2><small>⌖ ${factories[maint.factory].name} › ${a.area}</small></div><span class="maint-state ${maintenanceCategory(maint.index).toLowerCase()}">${a.risk}</span></div><div class="maintenance-view-tabs">${opButton('Assembly',"setMaintenanceView('assembly')",maint.view==='assembly'?'active':'')}${maint.index===0?opButton('Exploded view',"setMaintenanceView('exploded')",maint.view==='exploded'?'active':''):opButton('Parts detail','maintenancePartDetail(0)')}${opButton('Piping',"setMaintenanceView('piping')",maint.view==='piping'?'active':'')}${opButton('Explore 3D',"setMaintenanceView('engineering')",maint.view==='engineering'?'active':'')}</div>${maint.view==='piping'?maintenancePipingDiagram():maint.view==='engineering'?engineeringModelSlot(a.model,maint.index,true):`<div class="maintenance-render"><div class="maintenance-render-stage" id="maintenance-render-stage" style="transform:scale(${maint.zoom})"><img src="${maintAssetImage(maint.index,maint.view==='exploded')}" alt="${maint.view==='exploded'?'Exploded 3D-rendered pump assembly':'Photorealistic 3D-rendered '+a.name}">${maint.view==='assembly'?maintenanceHotspots():''}</div><span class="maintenance-render-caption">${maint.view==='exploded'?'Illustrative exploded assembly · Components aligned along the shaft':'Illustrative 3D render · Select a component for details'}</span><div class="maintenance-render-controls">${opButton('⌖','zoomMaintenance(0,true)')}${opButton('+','zoomMaintenance(.15)')}${opButton('−','zoomMaintenance(-.15)')}${opButton('Enlarge','enlargeMaintenanceAsset()')}</div></div>`}<div class="maintenance-assembly-actions">${opButton('Locate in factory','locateMaintenanceAsset()')}${opButton('Asset documents','maintenanceAssetDocuments()')}${opButton('Maintenance report','maintenanceRecord(maint.factory,maint.index)')}</div></section>`}
function maintenanceImpact(){const a=assets[maint.index],c=maintCondition[maint.index],j=jobFor(maint.index,maint.factory),category=maintenanceCategory(maint.index);return `<section class="panel maintenance-impact"><h2>Health & business impact</h2><div class="maintenance-health-grid"><div><small>Condition health</small><strong>${a.health}%</strong></div><div><small>Value at risk</small><strong>EGP ${nfmt(a.cost)}</strong></div></div><div class="maintenance-readings"><div data-viz-point="${escapeHTML(JSON.stringify({title:a.id+' condition',label:c.label,value:c.value,unit:c.unit,target:c.limit}))}"><small>${c.label}</small><strong>${c.value} <em>${c.unit}</em></strong><span>Reference limit: ${c.limit} ${c.unit}</span><div class="bar"><i style="width:${Math.min(100,c.value/(c.limit*1.3)*100)}%;background:${c.value>c.limit?'#ffd09d':'#a0f7da'}"></i></div></div><div><small>${c.second}</small><strong>${c.secondary}</strong></div><div><small>Run hours</small><strong>${nfmt(c.hours)} <em>h</em></strong></div></div><div class="maintenance-advisory ${category==='Critical'?'critical-advisory':''}"><strong>${category==='Healthy'?'Within operating range':a.risk}</strong><span>${category==='Healthy'?'Continue the planned inspection schedule.':'Plan inspection during '+a.due.toLowerCase()+'.'}</span><small>Illustrative advisory · Demo trend data</small></div><p class="assigned-technician">Assigned technician: <strong>${people.find(p=>p.id===j.assignee)?.name||'Not assigned'}</strong></p><div class="maintenance-impact-actions">${opButton('Assign qualified technician','assignMaintenanceAsset()','assign-maintenance')}${opButton('Detailed analysis','analyzeMaintenanceAsset()')}</div><div class="maintenance-work-state">Work order: <strong>${j.status}</strong> · ${factories[maint.factory].name}</div></section>`}
function maintenanceHistory(){const a=assets[maint.index],events=saved.events.filter(e=>e.factory===maint.factory&&e.message.includes(a.id)).slice(0,3);return `<section class="panel maintenance-history"><h2>Maintenance history</h2><ol>${events.map(e=>`<li><span class="history-marker"></span><div><strong>${escapeHTML(e.message)}</strong><small>${new Date(e.time).toLocaleString()}</small></div></li>`).join('')}${[['Last inspection','Routine inspection, condition assessed','04 Nov'],['Bearing lubrication','Lubrication checked · sample record','28 Oct'],['Seal review','Preventive service planned · sample record','12 Oct']].slice(0,Math.max(1,3-events.length)).map(e=>`<li><span class="history-marker"></span><div><strong>${e[0]}</strong><small>${e[1]}</small></div><time>${e[2]}</time></li>`).join('')}</ol></section>`}
function maintenancePartsPanel(){return `<section class="panel maintenance-parts"><h2>Parts & readiness</h2><table><tr><th>Component / Part</th><th>Part number</th><th>Stock</th><th>Readiness</th></tr>${maintParts[maint.index].map((p,i)=>{const requested=saved.partRequests?.some(r=>r.factory===maint.factory&&r.index===maint.index&&r.part===p.part);return `<tr><td><button class="part-name" onclick="maintenancePartDetail(${i})">${p.name}</button></td><td>${p.part}</td><td>${p.stock}</td><td>${p.stock?'<span class="part-ready">✓ Available</span>':requested?'<span class="part-requested">Requested</span>':`<button class="part-order" onclick="requestMaintenancePart(${i})">Order required</button>`}</td></tr>`}).join('')}</table></section>`}
maintenanceView=function(){if(state.factory>=0)maint.factory=state.factory;const rows=maintenanceRecords();if(rows.length&&!rows.some(r=>r.factory===maint.factory&&r.index===maint.index)){const preferred=rows.find(r=>r.factory===maint.factory)||rows[0];maint.factory=preferred.factory;maint.index=preferred.index;maint.view='assembly'}op.asset=maint.index;const a=assets[maint.index],c=maintCondition[maint.index];return `<div class="maintenance-topline"><h1>Maintenance <span>/ Asset intelligence</span></h1><div><label>Asset type<select onchange="setMaintenanceType(this.value)">${['All',...maintTypes].map(t=>`<option ${maint.type===t?'selected':''}>${t}</option>`).join('')}</select></label><label>Status<select onchange="setMaintenanceStatus(this.value)">${['All','Healthy','Attention','Critical','Planned service'].map(t=>`<option ${maint.status===t?'selected':''}>${t}</option>`).join('')}</select></label>${opButton('Work orders','maintenanceWorkOrders()','maintenance-work-orders')}</div></div><div class="maintenance-summary">${maintenanceSummary()}</div><div class="business-strip"><strong>Maintenance outlook</strong><span>Inspect health, locate equipment, assign qualified people and retain maintenance history.</span></div><div class="maintenance-main">${maintenanceAssetRegister(rows)}${rows.length?maintenanceAssembly()+maintenanceImpact():'<section class="panel maint-empty-large">No assets match these filters. '+opButton('Reset filters','resetMaintenanceFilters()')+'</section>'}</div>${rows.length?`<div class="maintenance-bottom">${analyticsChart('Condition trend',c.label+' · '+a.id+' · sample 24-hour profile',['00:00','04:00','08:00','12:00','16:00','20:00','24:00'],c.series,c.unit,{target:c.limit,viz:'area'})}${maintenanceHistory()}${maintenancePartsPanel()}</div>`:''}`};
function setMaintenanceView(view){if(!['assembly','exploded','piping','engineering'].includes(view))return;if(view==='exploded'&&maint.index!==0)return;maint.view=view;maint.zoom=1;render()}
function zoomMaintenance(delta,reset=false){maint.zoom=reset?1:Math.max(.7,Math.min(1.8,maint.zoom+delta));const frame=$('#maintenance-render-stage');if(frame)frame.style.transform='scale('+maint.zoom+')'}
function enlargeMaintenanceAsset(){openModal(selectedMaintenanceHeader(),`<div class="render-inspection"><img src="${maintAssetImage(maint.index,maint.view==='exploded')}" alt="Detailed 3D asset render"></div><p class="scope-label">${factories[maint.factory].name} · ${assets[maint.index].area} · Illustrative equipment</p>`);$('#modal').classList.add('wide-modal','equipment-modal')}
function maintenancePartDetail(partIndex){const a=assets[maint.index],p=maintParts[maint.index][partIndex];openModal(p?p.name:a.name,`<div class="scope-label">${factories[maint.factory].name} / ${a.id}</div><div class="modal-metrics"><div><small>Condition</small><h3>${a.reading}</h3></div><div><small>Reference</small><h3>${a.target}</h3></div>${p?`<div><small>Part number</small><h3>${p.part}</h3></div><div><small>Available stock</small><h3>${p.stock}</h3></div>`:''}</div><div class="actions">${opButton('Assign inspection','assignMaintenanceAsset()')}${p&&!p.stock?opButton('Request part',`requestMaintenancePart(${partIndex})`):''}${opButton('Equipment manual','maintenanceAssetDocuments()')}</div>`)}
function maintenanceAssetDocuments(){documentCenter('Maintenance','MAN-'+assets[maint.index].id.replaceAll('-',''))}
function locateMaintenanceAsset(){state.factory=maint.factory;op.asset=maint.index;locateAsset()}
function analyzeMaintenanceAsset(){const a=assets[maint.index],c=maintCondition[maint.index];openModal(a.id+' · Condition analysis',`<div class="scope-label">${factories[maint.factory].name} · Rule-based sample advisory</div>${analyticsChart('Condition evidence',c.label,['00','04','08','12','16','20','24'],c.series,c.unit,{target:c.limit,viz:'area'})}<p>${a.reading}. ${a.target}. Business exposure: EGP ${nfmt(a.cost)}.</p><p>The chart shows an illustrative measured trend. No live predictive model or remaining-life estimate is connected.</p><div class="actions">${opButton('Assign qualified person','assignMaintenanceAsset()')}${opButton('Maintenance history','maintenanceRecord(maint.factory,maint.index)')}</div>`)}
function assignMaintenanceAsset(){const a=assets[maint.index],eligible=people.filter(p=>p.valid&&p.skills.includes(a.skill));openModal('Assign '+a.id+' maintenance',`<p>${factories[maint.factory].name} · ${a.name}<br>Required qualification: <strong>${a.skill}</strong></p><label>Eligible technician<select id="maintenance-assignee">${eligible.map(p=>`<option value="${p.id}">${p.name} · valid to ${p.expiry}</option>`).join('')}</select></label><label class="note-label">Work instructions<textarea id="maintenance-job-note" rows="3" placeholder="Optional planning notes"></textarea></label><p class="note">Expired or unrelated qualifications are excluded.</p><div class="actions">${opButton('Assign demo work order',`assignNetworkWorkOrder(${maint.factory},${maint.index})`)}</div>`)}
function assignNetworkWorkOrder(factory,index){const p=people.find(p=>p.id===$('#maintenance-assignee')?.value),a=assets[index];if(!p||!p.valid||!p.skills.includes(a.skill)||!factories[factory])return;saved.jobs[factory+'-'+index]={assignee:p.id,status:'Assigned',note:($('#maintenance-job-note')?.value||'').trim().slice(0,500),assignedAt:new Date().toISOString()};eventLog(a.id+' assigned to '+p.name,'Maintenance',factory);render();maintenanceRecord(factory,index)}
function completeNetworkWorkOrder(factory,index){const j=jobFor(index,factory);if(!j.assignee||j.status==='Completed')return;saved.jobs[factory+'-'+index]={...j,status:'Completed',completedAt:new Date().toISOString()};eventLog(assets[index].id+' inspection completed in demo','Maintenance',factory);render();maintenanceRecord(factory,index)}
function maintenanceRecord(factory,index){const a=assets[index],j=jobFor(index,factory);openModal(a.id+' · Maintenance report',`<article class="maintenance-report"><span class="pill">DEMO RECORD · ${j.status}</span><dl><dt>Factory</dt><dd>${factories[factory].name}</dd><dt>Asset</dt><dd>${a.id} · ${a.name}</dd><dt>Required qualification</dt><dd>${a.skill}</dd><dt>Assigned technician</dt><dd>${people.find(p=>p.id===j.assignee)?.name||'Not assigned'}</dd><dt>Work instructions</dt><dd>${escapeHTML(j.note||'No notes recorded.')}</dd><dt>Current condition</dt><dd>${a.reading}</dd></dl><ol class="timeline">${saved.events.filter(e=>e.factory===factory&&e.message.includes(a.id)).map(e=>`<li>${new Date(e.time).toLocaleString()} — ${escapeHTML(e.message)}</li>`).join('')||'<li>No local work-order actions recorded yet.</li>'}</ol><p class="note">Completing an inspection records the work; it does not automatically clear the condition advisory.</p><div class="actions">${j.status==='Assigned'?opButton('Complete demo inspection',`completeNetworkWorkOrder(${factory},${index})`):''}${opButton('Download report',`downloadNetworkMaintenance(${factory},${index})`)}</div></article>`)}
function downloadNetworkMaintenance(factory,index){const a=assets[index],j=jobFor(index,factory);downloadable(a.id+'-'+factory+'-maintenance.html',`<!doctype html><html><head><meta charset="UTF-8"><title>${a.id} Maintenance report</title></head><body style="font:15px Arial;line-height:1.7;padding:35px"><h1>${a.id} · ${a.name}</h1><p>DEMONSTRATION RECORD · ${factories[factory].name}</p><p>Status: ${j.status}</p><p>Technician: ${people.find(p=>p.id===j.assignee)?.name||'Unassigned'}</p><p>Observed condition: ${a.reading}</p><p>Notes: ${escapeHTML(j.note||'')}</p></body></html>`,'text/html;charset=utf-8')}
function requestMaintenancePart(index){const p=maintParts[maint.index][index];if(!p||p.stock)return;saved.partRequests??=[];if(!saved.partRequests.some(r=>r.factory===maint.factory&&r.index===maint.index&&r.part===p.part))saved.partRequests.push({factory:maint.factory,index:maint.index,part:p.part,time:new Date().toISOString()});eventLog(assets[maint.index].id+' part request: '+p.part,'Maintenance',maint.factory);render();openModal('Part request recorded',`<p>${p.name} · ${p.part} · ${factories[maint.factory].name}</p><p>This request is stored in the local demonstration. No purchase order was transmitted.</p>`)}
function maintenanceWorkOrders(){const rows=maintenanceRecords(true);openModal('Maintenance work orders',`<div class="scope-label">${scopeName()} · ${rows.length} asset records</div><div class="table-scroll"><table><tr><th>Factory / Asset</th><th>Technician</th><th>Status</th><th></th></tr>${rows.map(r=>{const j=jobFor(r.index,r.factory);return `<tr><td>${factories[r.factory].name}<br><small>${r.asset.id} · ${r.asset.name}</small></td><td>${people.find(p=>p.id===j.assignee)?.name||'Not assigned'}</td><td>${j.status}</td><td>${opButton('Record',`maintenanceRecord(${r.factory},${r.index})`)}</td></tr>`}).join('')}</table></div><div class="actions">${opButton('Export work orders','exportMaintenanceWorkOrders()')}</div>`);$('#modal').classList.add('wide-modal')}
function compactWorkspaceTools(){openModal('Workspace tools',`<div class="entity-grid">${[['Documents','documentCenter()'],['Alarms','alarmCenter()'],['Reports','reportCenter()'],['Cameras','cameraCenter()'],['Weather','weatherCenter()']].map(x=>opButton(x[0],x[1])).join('')}</div>`)}
const pageMetricsBeforeMaintenanceIntelligence=pageMetrics;pageMetrics=function(){if(state.tab==='Maintenance'){const rows=maintenanceRecords(true);return [['Assets monitored',rows.length,'Selected factory scope'],['Healthy',rows.filter(r=>maintenanceCategory(r.index)==='Healthy').length,'Condition health ≥ 90%'],['Attention required',rows.filter(r=>maintenanceCategory(r.index)==='Attention').length,'Condition health 70–89%'],['Critical',rows.filter(r=>maintenanceCategory(r.index)==='Critical').length,'Condition health below 70%']]};return pageMetricsBeforeMaintenanceIntelligence()};
const goBeforeMaintenanceIntelligence=go;go=function(tab){if(tab==='Maintenance'&&Number.isInteger(op.asset)&&op.asset>=0&&op.asset<assets.length&&op.asset!==maint.index){maint.index=op.asset;maint.type='All';maint.status='All';maint.search='';maint.view='assembly'}goBeforeMaintenanceIntelligence(tab)};
const renderBeforeMaintenanceIntelligence=render;render=function(){document.body.classList.toggle('maintenance-intelligence-mode',state.tab==='Maintenance');renderBeforeMaintenanceIntelligence();document.title=state.tab+' | Life Science Operations';$('#nav .active')?.setAttribute('aria-current','page');if(!$('.compact-tools-button')){$('.controls')?.insertAdjacentHTML('beforeend',opButton('Tools ▾','compactWorkspaceTools()','compact-tools-button'))}if(state.tab==='Maintenance'){$('.maintenance-readings [data-viz-point]')?.setAttribute('tabindex','0')}};
function exportMaintenanceWorkOrders(){const rows=[['Factory','Asset','Name','Technician','Status'],...maintenanceRecords(true).map(r=>{const j=jobFor(r.index,r.factory);return [factories[r.factory].name,r.asset.id,r.asset.name,people.find(p=>p.id===j.assignee)?.name||'Not assigned',j.status]})];downloadable('maintenance-work-orders.csv','\ufeff'+rows.map(row=>row.map(v=>'"'+String(v).replaceAll('"','""')+'"').join(',')).join('\r\n'))}

render();
